// Package envfile renders the .env.prod file a Kuniel-shaped docker-compose
// project reads (domain/image/Postgres are always present; JWT, admin,
// email, and object storage are each optional blocks so this fits Spring
// Boot + Postgres projects that don't need all of them) — filled in from
// wizard answers instead of hand-edited.
package envfile

import (
	"bufio"
	"bytes"
	"fmt"
	"os"
	"strings"
	"text/template"
)

// Answers holds every value the compose project's .env.prod needs. The
// Has* fields gate whole sections of the generated file — false omits that
// section (and its keys) entirely rather than writing them out blank.
type Answers struct {
	AppDomain    string
	CertbotEmail string
	AppImage     string

	PostgresDB       string
	PostgresUser     string
	PostgresPassword string
	BackupKeepDays   string

	CorsAllowedOrigins string

	HasJWT         bool
	CertsMountPath string // e.g. /etc/app/certs — where certs/ is mounted in the app container

	HasAdmin      bool
	AdminEmail    string
	AdminPassword string
	AdminFullName string

	HasEmail     bool
	ResendAPIKey string
	ResendFrom   string

	HasObjectStorage bool
	S3Endpoint       string
	S3AccessKey      string
	S3SecretKey      string
	S3Bucket         string
	S3Region         string
}

const envTemplate = `# Generated by serv-kun springboot setup. Keep this out of git.

# --- Domain / TLS (nginx + certbot) ---
APP_DOMAIN={{.AppDomain}}
CERTBOT_EMAIL={{.CertbotEmail}}

# --- Docker image ---
APP_IMAGE={{.AppImage}}

# --- Postgres (self-hosted, internal network only) ---
POSTGRES_DB={{.PostgresDB}}
POSTGRES_USER={{.PostgresUser}}
POSTGRES_PASSWORD={{.PostgresPassword}}
SPRING_DATASOURCE_URL=jdbc:postgresql://postgres:5432/{{.PostgresDB}}
SPRING_DATASOURCE_USERNAME={{.PostgresUser}}
SPRING_DATASOURCE_PASSWORD={{.PostgresPassword}}
BACKUP_KEEP_DAYS={{.BackupKeepDays}}

# --- CORS: real origin(s) only ---
APP_CORS_ALLOWED_ORIGINS={{.CorsAllowedOrigins}}
{{if .HasJWT}}
# --- JWT (RS256) — generated into ./certs by this wizard ---
JWT_PUBLIC_KEY=file:{{.CertsMountPath}}/public.pem
JWT_PRIVATE_KEY=file:{{.CertsMountPath}}/private.pem
{{end}}{{if .HasAdmin}}
# --- Seeded admin organiser ---
APP_ADMIN_EMAIL={{.AdminEmail}}
APP_ADMIN_PASSWORD={{.AdminPassword}}
APP_ADMIN_FULL_NAME={{.AdminFullName}}
{{end}}{{if .HasEmail}}
# --- Email (Resend) ---
RESEND_API_KEY={{.ResendAPIKey}}
RESEND_FROM={{.ResendFrom}}
{{end}}{{if .HasObjectStorage}}
# --- Object storage (S3-compatible) ---
APP_S3_ENDPOINT={{.S3Endpoint}}
APP_S3_ACCESS_KEY={{.S3AccessKey}}
APP_S3_SECRET_KEY={{.S3SecretKey}}
APP_S3_BUCKET={{.S3Bucket}}
APP_S3_REGION={{.S3Region}}
{{end}}`

// Generate renders the .env.prod contents for the given answers.
func Generate(a Answers) (string, error) {
	tmpl, err := template.New("envfile").Parse(envTemplate)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, a); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// Read parses a KEY=VALUE env file (blank lines and #-comments ignored) —
// used to read back APP_DOMAIN/APP_IMAGE/etc. from an existing .env.prod,
// whether this wizard wrote it or it was hand-edited afterwards.
func Read(path string) (map[string]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", path, err)
	}
	defer f.Close()

	kv := make(map[string]string)
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}
		kv[strings.TrimSpace(parts[0])] = strings.TrimSpace(parts[1])
	}
	if err := sc.Err(); err != nil {
		return nil, fmt.Errorf("read %s: %w", path, err)
	}
	return kv, nil
}
